      return c.json(res.ok ? { ok: true, status: 'ready', url: res.url, cached: res.cached } : { ok: false, error: res.error });
    }
  } catch (e) {
    console.error('ai/scene error:', e);
    return c.json({ ok: false, error: e instanceof Error ? e.message : String(e) });
  }
});

