const MIN_ALARM_DELAY_MS = 50;

/** Cheap per-minute in-DO rate limit (doc 16 §12) — override with REFLEX_RATE_LIMIT_PER_MIN. */
const DEFAULT_RATE_LIMIT_PER_MIN = 240;

const DEFAULT_RETENTION_DAYS = 30;

/**
